-- 3. Project (English = default language)
INSERT INTO pws_posts (post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count)
VALUES (@ga_author, @ga_now, @ga_now_gmt, '<!-- wp:paragraph --><p>In 2008 the iPhone 3G and the App Store had just launched, and a club night in Switzerland still ran almost entirely on cash: long queues at the door, change, counting the till at five in the morning. At QT Records we sketched QTPass: the guest\'s phone as ticket, ID and wallet.</p><!-- /wp:paragraph -->\n\n<!-- wp:paragraph --><p>The guest registers once with their mobile number and shows an ID on the first visit. They top up a prepaid credit by card or by premium SMS charged to the phone bill (carrier billing). At the door the iPhone app shows a six-digit one-time code (HOTP, RFC 4226) that it computes without network, because basement clubs have no signal. Door staff type the code, the terminal shows the guest\'s photo and age, and the entry fee is debited. Guests without an iPhone send IN and their member number by SMS and get the code back.</p><!-- /wp:paragraph -->\n\n<!-- wp:paragraph --><p>The design keeps strictly to the technology of 2008: Objective-C with manual memory management on iPhone OS 2.x, PHP 5.2 and MySQL 5.0, an SMS aggregator connected to Swisscom, Sunrise and Orange, and a Mac mini in the club as an offline node. It also covers the Swiss legal questions of the time: banking and anti-money-laundering law, price disclosure for value-added services, data protection and youth protection.</p><!-- /wp:paragraph -->\n\n<!-- wp:paragraph --><p>The project was discontinued before development. A single venue could not carry the fixed costs, the carriers kept a large share of every SMS top-up, and the legal status of the prepaid credit was uncertain. Six years later TWINT solved the same problem with a nationwide network of banks.</p><!-- /wp:paragraph -->\n\n<!-- wp:paragraph --><p>The repository is a reconstruction written in 2026: documentation, process model, architecture and draft code, limited to what was technically possible in 2008.</p><!-- /wp:paragraph -->', 'QTPass — Pay by Phone at the Club Door (2008)', 'A 2008 concept from QT Records: guests pay entry and drinks at an EDM club with their phone. One-time codes in an iPhone app, SMS for every other phone, carrier billing and a prepaid credit. A rudimentary forerunner of TWINT, never built and discontinued.', 'publish', 'closed', 'closed', '', 'qtpass-2008', '', '', @ga_now, @ga_now_gmt, '', 0, '', @ga_order, 'ga_project', '', 0);
SET @ga_pid = LAST_INSERT_ID();
UPDATE pws_posts SET guid = CONCAT((SELECT option_value FROM (SELECT option_value FROM pws_options WHERE option_name = 'home') o), '/?post_type=ga_project&p=', @ga_pid) WHERE ID = @ga_pid;

